mapper.select:
SELECT
FROM goods g LEFT JOIN category c ON c.id = g.category_id AND c.deleted = 0 LEFT JOIN craftsman cs ON cs.id = g.craftsman_id AND cs.deleted = 0 LEFT JOIN ( SELECT target_id, ROUND(AVG(rating), 1) AS rating_avg, COUNT(*) AS review_count FROM review WHERE type = 1 AND deleted = 0 GROUP BY target_id ) rv ON rv.target_id = g.id
g.deleted = 0 AND g.status = 1 AND g.audit_status = 1
AND g.category_id = #{q.categoryId}
AND g.craftsman_id = #{q.craftsmanId}
AND g.is_handmade = #{q.isHandmade}
AND g.price >= #{q.minPrice}
AND g.price <= #{q.maxPrice}
AND ( g.name LIKE CONCAT('%', #{q.keyword}, '%') OR g.subtitle LIKE CONCAT('%', #{q.keyword}, '%') OR g.description LIKE CONCAT('%', #{q.keyword}, '%') )
ORDER BY g.sales DESC, g.id DESC
ORDER BY g.price ASC, g.id DESC
ORDER BY g.price DESC, g.id DESC
ORDER BY g.create_time DESC, g.id DESC
ORDER BY g.sales DESC, g.view_count DESC, g.id DESC

SELECT g.id, g.name, g.subtitle, g.cover, g.price, g.original_price, g.stock, g.sales, g.view_count, g.is_handmade, g.status, g.audit_status, g.reject_reason, g.category_id, g.create_time, g.update_time, c.name AS category_name, rv.rating_avg AS rating_avg, rv.review_count AS review_count FROM goods g LEFT JOIN category c ON c.id = g.category_id AND c.deleted = 0 LEFT JOIN ( SELECT target_id, ROUND(AVG(rating), 1) AS rating_avg, COUNT(*) AS review_count FROM review WHERE type = 1 AND deleted = 0 GROUP BY target_id ) rv ON rv.target_id = g.id
g.deleted = 0 AND g.craftsman_id = #{craftsmanId}
AND g.status = #{q.status}
AND g.audit_status = #{q.auditStatus}
AND g.category_id = #{q.categoryId}
AND g.status = 1 AND g.audit_status = 1 AND g.stock <= #{q.stockWarnThreshold}
AND ( g.name LIKE CONCAT('%', #{q.keyword}, '%') OR g.subtitle LIKE CONCAT('%', #{q.keyword}, '%') )
ORDER BY g.sales DESC, g.id DESC
ORDER BY g.stock ASC, g.id DESC
ORDER BY g.view_count DESC, g.id DESC
ORDER BY g.id DESC

SELECT g.id, g.name, g.subtitle, g.cover, g.price, g.original_price, g.stock, g.sales, g.view_count, g.is_handmade, g.status, g.audit_status, g.reject_reason, g.category_id, g.craftsman_id, g.create_time, g.update_time, c.name AS category_name, cr.real_name AS craftsman_name, cr.craft_type AS craft_type, rv.rating_avg AS rating_avg, rv.review_count AS review_count FROM goods g LEFT JOIN category c ON c.id = g.category_id AND c.deleted = 0 LEFT JOIN craftsman cr ON cr.id = g.craftsman_id AND cr.deleted = 0 LEFT JOIN ( SELECT target_id, ROUND(AVG(rating), 1) AS rating_avg, COUNT(*) AS review_count FROM review WHERE type = 1 AND deleted = 0 GROUP BY target_id ) rv ON rv.target_id = g.id
g.deleted = 0
AND g.status = #{q.status}
AND g.audit_status = #{q.auditStatus}
AND g.category_id = #{q.categoryId}
AND g.craftsman_id = #{q.craftsmanId}
AND g.price >= #{q.minPrice}
AND g.price <= #{q.maxPrice}
AND (g.name LIKE CONCAT('%', #{q.keyword}, '%') OR g.subtitle LIKE CONCAT('%', #{q.keyword}, '%') OR cr.real_name LIKE CONCAT('%', #{q.keyword}, '%'))
AND g.create_time >= #{q.startTime}
AND g.create_time <= #{q.endTime}
ORDER BY g.sales DESC, g.id DESC
ORDER BY g.stock ASC, g.id DESC
ORDER BY g.price DESC, g.id DESC
ORDER BY g.view_count DESC, g.id DESC
ORDER BY g.create_time DESC, g.id DESC
